import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import java.util.stream.*;


public class E {

    private static final FastReader in = new FastReader();
    private static final FastWriter out = new FastWriter();

    public static void main(String[] args) {
        new E().run();
    }

    private void run() {
        int t = 1;
        do {
            solve();
        } while (--t > 0);
        out.flush();
    }

    private void solve() {
        int n = in.nextInt();
        long k = in.nextLong();

        if (k >= n) {
            out.println(0);
            return;
        }

        int kInt = (int) k;
        Modulo mod = new Modulo(998244353);
        long[] fact = mod.factorials(n);

        long ans = 0L;
        int c = n - kInt;
        for (int i = 0; i <= c; ++i) {
            long term = mod.times(mod.combination(c, i, fact), mod.pow(c - i, n));
            if ((i & 1) == 0) {
                ans = mod.plus(ans, term);
            } else {
                ans = mod.minus(ans, term);
            }
        }
        ans = mod.times(ans, mod.combination(n, n - kInt, fact));
        if (kInt > 0) {
            ans = mod.times(ans, 2L);
        }
        out.println(ans);
    }

}


class FastReader {

    private static final BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    private StringTokenizer st;

    public String next() {
        while (st == null || !st.hasMoreTokens()) {
            try {
                st = new StringTokenizer(br.readLine());
            } catch (IOException e) {
                return null;
            }
        }
        return st.nextToken();
    }

    public int nextInt() {
        return Integer.parseInt(next());
    }

    public long nextLong() {
        return Long.parseLong(next());
    }

    public double nextDouble() {
        return Double.parseDouble(next());
    }

    public BigDecimal nextBigDecimal() {
        return new BigDecimal(next());
    }

    public BigInteger nextBigInteger() {
        return new BigInteger(next());
    }

    public boolean nextBoolean() {
        return Boolean.parseBoolean(next());
    }

    public byte nextByte() {
        return Byte.parseByte(next());
    }

    public int[] nextIntArray(int length) {
        int[] a = new int[length];
        for (int i = 0; i < length; i++) a[i] = nextInt();
        return a;
    }

    public long[] nextLongArray(int length) {
        long[] a = new long[length];
        for (int i = 0; i < length; i++) a[i] = nextLong();
        return a;
    }

    public double[] nextDoubleArray(int length) {
        double[] a = new double[length];
        for (int i = 0; i < length; i++) a[i] = nextDouble();
        return a;
    }

}


class FastWriter extends PrintWriter {

    public FastWriter() {
        super(System.out);
    }

    public void println(boolean[] a) {
        for (int i = 0; i < a.length; i++) {
            print(a[i]);
            if (i + 1 < a.length) print(' '); else println();
        }
    }

    public void println(double[] a) {
        for (int i = 0; i < a.length; i++) {
            print(a[i]);
            if (i + 1 < a.length) print(' '); else println();
        }
    }

    public void println(int[] a) {
        for (int i = 0; i < a.length; i++) {
            print(a[i]);
            if (i + 1 < a.length) print(' '); else println();
        }
    }

    public void println(long[] a) {
        for (int i = 0; i < a.length; i++) {
            print(a[i]);
            if (i + 1 < a.length) print(' '); else println();
        }
    }

    public void println(Object... a) {
        for (int i = 0; i < a.length; i++) {
            print(a[i]);
            if (i + 1 < a.length) print(' '); else println();
        }
    }

    public <T> void println(List<T> l) {
        println(l.toArray());
    }

    public void debug(String name, Object o) {
        String value = Arrays.deepToString(new Object[]{o});
        value = value.substring(1, value.length() - 1);
        System.err.println(name + " => " + value);
    }

}


class Modulo {

    private final long mod;

    public Modulo(long mod) {
        this.mod = mod;
    }

    public long add(long a, long b) {
        long c = a + b;
        if (c >= mod) c -= mod;
        return c;
    }

    public long subtract(long a, long b) {
        long c = a - b;
        if (c < 0) c += mod;
        return c;
    }

    public long multiply(long a, long b) {
        return (a * b) % mod;
    }

    public long divide(long a, long b) {
        return multiply(a, pow(b, mod - 2));
    }

    public long pow(long a, long b) {
        long res = 1;
        while (b > 0) {
            if ((b & 1) == 1) res = (res * a) % mod;
            a = (a * a) % mod;
            b >>= 1;
        }
        return res;
    }

    public long combination(int n, int k, long[] facts) {
        if (k < 0 || k > n) return 0;
        return divide(facts[n], multiply(facts[k], facts[n - k]));
    }

    public long[] factorials(int n) {
        long[] f = new long[n + 1];
        f[0] = 1;
        for (int i = 1; i <= n; i++) f[i] = (f[i - 1] * i) % mod;
        return f;
    }

}
